mapper.update:
UPDATE oa_consumable SET quantity = #{record.quantity}, stock_amount = #{record.stockAmount},
    avg_cost = #{record.avgCost}, last_purchase_price = #{record.lastPurchasePrice},
    last_calc_time = #{record.lastCalcTime}, version = version + 1,
    update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE tenant_id = #{record.tenantId} AND consumable_id = #{record.consumableId}
    AND deleted = 0 AND version = #{record.version}

UPDATE oa_consumable SET name = #{record.name}, model = #{record.model}, unit = #{record.unit},
    category_id = #{record.categoryId}, brand = #{record.brand}, low_stock_threshold = #{record.lowStockThreshold},
    target_stock = #{record.targetStock}, max_stock = #{record.maxStock}, default_supplier_id = #{record.defaultSupplierId},
    warn_enabled = #{record.warnEnabled}, storage_location = #{record.storageLocation}, status = #{record.status},
    version = version + 1, update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE tenant_id = #{record.tenantId} AND consumable_id = #{record.consumableId}
    AND deleted = 0 AND version = #{record.version}

UPDATE oa_consumable SET deleted = 1, version = version + 1,
    update_by = #{record.updateBy}, update_time = #{record.updateTime}
WHERE tenant_id = #{record.tenantId} AND consumable_id = #{record.consumableId}
    AND deleted = 0 AND version = #{record.version} AND quantity = 0 AND stock_amount = 0
